    color: String,

    /// Path to configuration file
    #[arg(long, global = true)]
    config: Option<String>,

    /// Ignore all configuration files and use built-in defaults
    #[arg(long, global = true)]
    no_config: bool,

    /// Ignore all configuration files (alias for --no-config)
    #[arg(long, global = true)]
    isolated: bool,

    #[arg(short = 'V', long, global = true)]
    version: bool,

    #[arg(short = 'h', long, global = true)]
    help: bool,
}

#[derive(Subcommand)]
enum Command {
    /// Lint Markdown files and print warnings/errors
    Check(CheckArgs),

    /// Format Markdown files (alias for check --fix)
    Fmt(CheckArgs),

    /// Initialize a new configuration file
    Init(InitArgs),

    /// Show information about a rule or list all rules
    Rule(RuleArgs),

    /// Explain a rule with detailed information and examples
    Explain(ExplainArgs),

    /// Show configuration or query a specific key
    Config(ConfigArgs),

    /// Start the Language Server Protocol server
    Server,

    /// Generate or check JSON schema for rumdl.toml
    Schema(SchemaArgs),

    /// Import and convert markdownlint configuration files
    Import(ImportArgs),

    /// Install the rumdl VS Code extension
    Vscode(VscodeArgs),

    /// Generate shell completion scripts
    Completions(CompletionsArgs),

    /// Clear the cache
    Clean,

    /// Show version information
    Version,

    #[command(hide = true)]
    Help,
}

#[derive(Parser)]
struct CheckArgs {
    /// Files or directories to lint (use '-' for stdin)
    #[arg(value_name = "PATHS")]
    paths: Vec<String>,

    #[arg(short, long)]
    fix: bool,

    /// Show diff of what would be fixed instead of fixing files
    #[arg(long)]
    diff: bool,

    /// Exit with code 1 if any formatting changes would be made (for CI)
    #[arg(long)]
    check: bool,

    /// List all available rules
    #[arg(short = 'l', long)]
    list_rules: bool,

    /// Disable specific rules (comma-separated)
    #[arg(short = 'd', long)]
    disable: Option<String>,

    /// Enable only specific rules (comma-separated)
    #[arg(short = 'e', long, alias = "rules")]
    enable: Option<String>,

    /// Extend the list of enabled rules (additive with config)
    #[arg(long)]
    extend_enable: Option<String>,

    /// Extend the list of disabled rules (additive with config)
    #[arg(long)]
    extend_disable: Option<String>,

    /// Exclude specific files or directories (comma-separated glob patterns)
    #[arg(long)]
    exclude: Option<String>,

    /// Disable all exclude patterns
    #[arg(long)]
    no_exclude: bool,

    /// Include only specific files or directories (comma-separated glob patterns)
    #[arg(long)]
    include: Option<String>,

    /// Respect .gitignore files when scanning directories
    #[arg(long, value_name = "RESPECT_GITIGNORE")]
    respect_gitignore: Option<String>,

    /// Show detailed output
    #[arg(short = 'v', long)]
    verbose: bool,

    /// Control colored output
    #[arg(long)]
    color: Option<String>,

    /// Show profiling information
    #[arg(long)]
    profile: bool,

    /// Path to configuration file
    #[arg(long)]
    config: Option<String>,

    /// Show statistics summary of rule violations
    #[arg(long)]
    statistics: bool,

    /// Ignore all configuration files and use built-in defaults
    #[arg(long)]
    no_config: bool,

    /// Suppress output except errors
    #[arg(short = 'q', long)]
    quiet: bool,

    /// Ignore all configuration files (alias for --no-config)
    #[arg(long)]
    isolated: bool,

    /// Output format
    #[arg(short = 'o', long)]
    output: Option<String>,

    /// Output format
    #[arg(long)]
    output_format: Option<String>,

    /// Show absolute file paths in output instead of relative paths
    #[arg(long)]
    show_full_path: bool,

    /// Markdown flavor
    #[arg(long)]
    flavor: Option<String>,

    /// Read from stdin instead of files
    #[arg(long)]
    stdin: bool,

    /// Filename to use when reading from stdin
    #[arg(long)]
    stdin_filename: Option<String>,

    /// Output diagnostics to stderr instead of stdout
    #[arg(long)]
    stderr: bool,

    /// Disable all logging
    #[arg(short = 's', long)]
    silent: bool,

    /// Run in watch mode
    #[arg(short = 'w', long)]
    watch: bool,

    /// Enforce exclude patterns even for explicitly specified files
    #[arg(long)]
    force_exclude: bool,

    /// Disable caching
    #[arg(long)]
    no_cache: bool,

    /// Directory to store cache files
    #[arg(long)]
    cache_dir: Option<String>,

    /// Exit code behavior
    #[arg(long)]
    fail_on: Option<String>,
}

#[derive(Parser)]
struct InitArgs {
    /// Generate configuration for pyproject.toml instead of .rumdl.toml
    #[arg(long)]
    pyproject: bool,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Parser)]
struct RuleArgs {
    /// Rule name or ID (optional, omit to list all rules)
    rule: Option<String>,

    /// Output format
    #[arg(short = 'o', long, default_value = "text")]
    output_format: String,

    /// Filter to only fixable rules
    #[arg(short = 'f', long)]
    fixable: bool,

    /// Filter by category
    #[arg(short = 'c', long)]
    category: Option<String>,

    /// Include full documentation in output (for json/json-lines)
    #[arg(long)]
    explain: bool,

    /// List available categories and exit
    #[arg(long)]
    list_categories: bool,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Parser)]
struct ExplainArgs {
    /// Rule name or ID to explain
    rule: String,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Parser)]
struct ConfigArgs {
    #[command(subcommand)]
    command: Option<ConfigCommand>,

    #[arg(long)]
    defaults: bool,

    #[arg(long)]
    no_defaults: bool,

    #[arg(long)]
    output: Option<String>,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Subcommand)]
enum ConfigCommand {
    /// Query a specific config key
    Get { key: String },
    /// Show the absolute path of the configuration file that was loaded
    File,
}

#[derive(Parser)]
struct SchemaArgs {
    #[command(subcommand)]
    command: SchemaCommand,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Subcommand)]
enum SchemaCommand {
    /// Generate/update the JSON schema file
    Generate,
    /// Check if the schema is up-to-date
    Check,
    /// Print the schema to stdout
    Print,
}

#[derive(Parser)]
struct ImportArgs {
    /// Path to markdownlint config file (JSON/YAML)
    file: String,

    /// Output file path
    #[arg(short = 'o', long, default_value = ".rumdl.toml")]
    output: String,

    /// Output format
    #[arg(long, default_value = "toml")]
    format: String,

    /// Show converted config without writing to file
    #[arg(long)]
    dry_run: bool,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Parser)]
struct VscodeArgs {
    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

#[derive(Parser)]
struct CompletionsArgs {
    /// Shell to generate completions for
    shell: Option<String>,

    /// List available shells
    #[arg(short = 'l', long)]
    list: bool,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    config: Option<String>,

    #[arg(long)]
    no_config: bool,

    #[arg(long)]
    isolated: bool,
}

fn main() {
    println!("rumdl 0.1.13");
}
